import type { ImgHTMLAttributes } from "react";

// WebP variants generated by `npm run images` (scripts/optimize-images.mjs)
const files = import.meta.glob<string>("/src/assets/optimized/*.webp", {
  eager: true,
  query: "?url",
  import: "default",
});

function variantsOf(name: string) {
  return Object.entries(files)
    .map(([file, url]) => {
      const match = file.match(/\/([\w-]+)-(\d+)\.webp$/);
      return match && match[1] === name ? { width: Number(match[2]), url } : null;
    })
    .filter((v): v is { width: number; url: string } => v !== null)
    .sort((a, b) => a.width - b.width);
}

type Props = Omit<ImgHTMLAttributes<HTMLImageElement>, "src" | "srcSet" | "alt"> & {
  /** Base file name in src/assets, e.g. "tour-christ" */
  name: string;
  alt: string;
  /** Rendered width hint so the browser downloads the smallest sufficient file, e.g. "(min-width: 1024px) 33vw, 100vw" */
  sizes: string;
};

export function ResponsiveImage({ name, sizes, alt, ...rest }: Props) {
  const variants = variantsOf(name);
  if (!variants.length) return null;
  const largest = variants[variants.length - 1];
  return (
    <img
      src={largest.url}
      srcSet={variants.map((v) => `${v.url} ${v.width}w`).join(", ")}
      sizes={sizes}
      alt={alt}
      decoding="async"
      {...rest}
    />
  );
}
